39	// csrc/scan/mamba_scan_adapter.cuh — CUDA scan adapter.
40	// Moved here in Phase 4 of the refactor because the Mamba selective scan is
41	// shared between the Mamba model kernels and the SuperGrok v2 optimizer.
42	//
43	// Thin adapter wrapping SG2's existing mamba3_* scan kernels for model-context
44	// use. No reimplementation of the core scan algorithm — reuses the Affine2x2
45	// parallel-prefix infrastructure from csrc/scan/affine2x2.h.
46	//
47	// The adapter packs model-level (x, dt, A_log, B, C) into Affine2x2 maps:
48	//   A_bar = exp(dt * A),  B_bar = dt * B
49	//   Affine2x2: M = diag(A_bar_s0, A_bar_s1),  b = (B_bar_s0*x, B_bar_s1*x)
50	// then calls the Blelloch parallel-prefix scan for medium/large N, or a
51	// simple sequential scan for small N.
52	//
53	// Decision tree (thresholds from csrc/common/types.h):
54	//   N < PSCAN_THRESHOLD (256)               -> sequential scan kernel
55	//   256 <= N < GEMM_PRECOMPUTE_THRESHOLD    -> parallel Blelloch scan
56	//   N >= GEMM_PRECOMPUTE_THRESHOLD (1024)   -> parallel Blelloch scan (same kernel)
57	
58	
59	
60	namespace sg { namespace sm90 { namespace models { namespace mamba_adapter {
61	
62	// ── Dtype cast helpers (intrinsic-based) ──────────────────────────────
63	// A bare static_cast between {__half,__nv_bfloat16} and float is rejected
64	// under torch's -D__CUDA_NO_HALF_CONVERSIONS__ / -D__CUDA_NO_BFLOAT16_CONVERSIONS__
65	// (the CUDAExtension default, which strips operator float()/the float ctor).
66	// Route every half/bf16<->float conversion through the always-available
67	// conversion intrinsics; the generic templates keep float/int casts unchanged.
68	template <typename T> __device__ __forceinline__ float to_float(T v) { return static_cast<float>(v); }
69	template <> __device__ __forceinline__ float to_float<__half>(__half v) { return __half2float(v); }
70	template <> __device__ __forceinline__ float to_float<__nv_bfloat16>(__nv_bfloat16 v) { return __bfloat162float(v); }
71	template <typename T> __device__ __forceinline__ T from_float(float v) { return static_cast<T>(v); }
72	template <> __device__ __forceinline__ __half from_float<__half>(float v) { return __float2half(v); }
73	template <> __device__ __forceinline__ __nv_bfloat16 from_float<__nv_bfloat16>(float v) { return __float2bfloat16(v); }
74	
75	// ── Sequential scan kernel (N < PSCAN_THRESHOLD) ──────────────────────
76	// One thread per d_inner dimension, sequential over timesteps.
77	
78	template <typename ActT>
79	__global__ void __launch_bounds__(128, 4)
80	sequential_scan_kernel(
81	    const ActT* __restrict__ x,       // [B, N, d_inner]
82	    const ActT* __restrict__ dt,      // [B, N, d_inner]
83	    const ActT* __restrict__ A_log,   // [d_inner, d_state]
84	    const ActT* __restrict__ B,       // [B, N, d_state]
85	    const ActT* __restrict__ C,       // [B, N, d_state]
86	    ActT* __restrict__ y,             // [B, N, d_inner]
87	    float* __restrict__ state_save,   // [B, d_inner, d_state] or nullptr
88	    int seq_len, int d_inner, int d_state
89	) {
90	    const int b = blockIdx.y;
91	    const int j = blockIdx.x * blockDim.x + threadIdx.x;
92	    if (j >= d_inner) return;
93	
94	    const int bN  = b * seq_len;
95	    const int bDi = b * d_inner;
96	
97	    float A[MAX_D_STATE];
98	    #pragma unroll 4
99	    for (int s = 0; s < d_state; s++)
100	        A[s] = -ptx_expf(to_float(A_log[j * d_state + s]));
101	
102	    float h[MAX_D_STATE];
103	    #pragma unroll 4
104	    for (int s = 0; s < d_state; s++) h[s] = 0.0f;
105	
106	    for (int t = 0; t < seq_len; t++) {
107	        float x_val  = to_float(x[(bN + t) * d_inner + j]);
108	        float dt_val = to_float(dt[(bN + t) * d_inner + j]);
109	        float y_acc  = 0.0f;
110	
111	        #pragma unroll 4
112	        for (int s = 0; s < d_state; s++) {
113	            float A_bar = ptx_expf(A[s] * dt_val);
114	            float B_bar = dt_val * to_float(B[(bN + t) * d_state + s]);
115	            h[s] = A_bar * h[s] + B_bar * x_val;
116	            y_acc += to_float(C[(bN + t) * d_state + s]) * h[s];
117	        }
118	        y[(bN + t) * d_inner + j] = from_float<ActT>(y_acc);
119	    }
120	
121	    if (state_save != nullptr) {
122	        #pragma unroll 4
123	        for (int s = 0; s < d_state; s++)
124	            state_save[(bDi + j) * d_state + s] = h[s];
125	    }
126	}
127	
128	// ── Parallel Blelloch scan kernel (N >= PSCAN_THRESHOLD) ──────────────
129	// One block per (batch, d_inner). Affine2x2 prefix scan across timesteps,
130	// processing d_state pairs two at a time through the 2x2 matrix machinery.
131	
132	template <typename ActT>
133	__global__ void __launch_bounds__(256, 2)
134	parallel_scan_kernel(
135	    const ActT* __restrict__ x,
136	    const ActT* __restrict__ dt,
137	    const ActT* __restrict__ A_log,
138	    const ActT* __restrict__ B,
139	    const ActT* __restrict__ C,
140	    ActT* __restrict__ y,
141	    float* __restrict__ state_save,
142	    int seq_len, int d_inner, int d_state
143	) {
144	    const int b = blockIdx.y;
145	    const int j = blockIdx.x;
146	    if (j >= d_inner) return;
147	    const int ltid = threadIdx.x;
148	    const int nthreads = blockDim.x;
149	    const int N = seq_len;
150	    const int bN = b * N;
151	    const int bDi = b * d_inner;
152	
153	    extern __shared__ float smem[];  // 6 * nthreads
154	
155	    const int chunk = (N + nthreads - 1) / nthreads;
156	    const int t0 = ltid * chunk;
157	    const int t1 = min(t0 + chunk, N);
158	    const int cnt = max(t1 - t0, 0);
159	
160	    float A_coeff[MAX_D_STATE];
161	    #pragma unroll 4
162	    for (int s = 0; s < d_state; s++)
163	        A_coeff[s] = -ptx_expf(to_float(A_log[j * d_state + s]));
164	
165	    // Zero output for accumulation across d_state pairs
166	    for (int step = 0; step < cnt; step++) {
167	        y[(bN + t0 + step) * d_inner + j] = from_float<ActT>(0.0f);
168	    }
169	    __syncthreads();
170	
171	    const int half_ds = d_state / 2;
172	
173	    for (int p = 0; p < half_ds; p++) {
174	        const int s0 = 2 * p, s1 = 2 * p + 1;
175	
176	        // Phase 1: sequential scan within chunk -> summary Affine2x2
177	        Affine2x2 summary = affine_identity();
178	        #pragma unroll 4
179	        for (int step = 0; step < cnt; step++) {
180	            int t = t0 + step;
181	            float dtv = to_float(dt[(bN + t) * d_inner + j]);
182	            float xv  = to_float(x[(bN + t) * d_inner + j]);
183	            Affine2x2 elem;
184	            elem.m00 = ptx_expf(A_coeff[s0] * dtv);  elem.m01 = 0.0f;
185	            elem.m10 = 0.0f;                          elem.m11 = ptx_expf(A_coeff[s1] * dtv);
186	            elem.b0  = dtv * to_float(B[(bN + t) * d_state + s0]) * xv;
187	            elem.b1  = dtv * to_float(B[(bN + t) * d_state + s1]) * xv;
188	            summary = affine_combine(summary, elem);
189	        }
190	
191	        int base = ltid * 6;
192	        smem[base]   = summary.m00; smem[base+1] = summary.m01;
193	        smem[base+2] = summary.m10; smem[base+3] = summary.m11;
194	        smem[base+4] = summary.b0;  smem[base+5] = summary.b1;
195	        __syncthreads();
196	
197	        // Phase 2: Blelloch up-sweep
198	        for (int stride = 1; stride < nthreads; stride *= 2) {
199	            int idx = (ltid + 1) * stride * 2 - 1;
200	            if (idx < nthreads) {
201	                Affine2x2 L = {smem[(idx-stride)*6],   smem[(idx-stride)*6+1],
202	                               smem[(idx-stride)*6+2], smem[(idx-stride)*6+3],
203	                               smem[(idx-stride)*6+4], smem[(idx-stride)*6+5]};
204	                Affine2x2 R = {smem[idx*6],   smem[idx*6+1],
205	                               smem[idx*6+2], smem[idx*6+3],
206	                               smem[idx*6+4], smem[idx*6+5]};
207	                Affine2x2 c = affine_combine(L, R);
208	                smem[idx*6]=c.m00; smem[idx*6+1]=c.m01; smem[idx*6+2]=c.m10;
209	                smem[idx*6+3]=c.m11; smem[idx*6+4]=c.b0; smem[idx*6+5]=c.b1;
210	            }
211	            __syncthreads();
212	        }
213	
214	        // Set last to identity (exclusive scan)
215	        if (ltid == 0) {
216	            int last = (nthreads - 1) * 6;
217	            smem[last]=1; smem[last+1]=0; smem[last+2]=0;
218	            smem[last+3]=1; smem[last+4]=0; smem[last+5]=0;
219	        }
220	        __syncthreads();
221	
222	        // Down-sweep
223	        for (int stride = nthreads / 2; stride >= 1; stride /= 2) {
224	            int idx = (ltid + 1) * stride * 2 - 1;
225	            if (idx < nthreads) {
226	                Affine2x2 L = {smem[(idx-stride)*6],   smem[(idx-stride)*6+1],
227	                               smem[(idx-stride)*6+2], smem[(idx-stride)*6+3],
228	                               smem[(idx-stride)*6+4], smem[(idx-stride)*6+5]};
229	                Affine2x2 R = {smem[idx*6],   smem[idx*6+1],
230	                               smem[idx*6+2], smem[idx*6+3],
231	                               smem[idx*6+4], smem[idx*6+5]};
232	                smem[(idx-stride)*6]=R.m00; smem[(idx-stride)*6+1]=R.m01;
233	                smem[(idx-stride)*6+2]=R.m10; smem[(idx-stride)*6+3]=R.m11;
234	                smem[(idx-stride)*6+4]=R.b0; smem[(idx-stride)*6+5]=R.b1;
235	                Affine2x2 c = affine_combine(R, L);
236	                smem[idx*6]=c.m00; smem[idx*6+1]=c.m01; smem[idx*6+2]=c.m10;
237	                smem[idx*6+3]=c.m11; smem[idx*6+4]=c.b0; smem[idx*6+5]=c.b1;
238	            }
239	            __syncthreads();
240	        }
241	
242	        // Phase 3: re-scan with prefix, accumulate output
243	        Affine2x2 run = {smem[ltid*6], smem[ltid*6+1], smem[ltid*6+2],
244	                         smem[ltid*6+3], smem[ltid*6+4], smem[ltid*6+5]};
245	        #pragma unroll 4
246	        for (int step = 0; step < cnt; step++) {
247	            int t = t0 + step;
248	            float dtv = to_float(dt[(bN + t) * d_inner + j]);
249	            float xv  = to_float(x[(bN + t) * d_inner + j]);
250	            Affine2x2 elem;
251	            elem.m00 = ptx_expf(A_coeff[s0] * dtv);  elem.m01 = 0.0f;
252	            elem.m10 = 0.0f;                          elem.m11 = ptx_expf(A_coeff[s1] * dtv);
253	            elem.b0  = dtv * to_float(B[(bN + t) * d_state + s0]) * xv;
254	            elem.b1  = dtv * to_float(B[(bN + t) * d_state + s1]) * xv;
255	            run = affine_combine(run, elem);
256	
257	            // h = run applied to zero initial state -> h = run.b
258	            float c0 = to_float(C[(bN + t) * d_state + s0]);
259	            float c1 = to_float(C[(bN + t) * d_state + s1]);
260	            float prev = to_float(y[(bN + t) * d_inner + j]);
261	            y[(bN + t) * d_inner + j] = from_float<ActT>(prev + run.b0*c0 + run.b1*c1);
262	        }
263	
264	        if (state_save != nullptr && t1 == N && cnt > 0) {
265	            state_save[(bDi + j) * d_state + s0] = run.b0;
266	            state_save[(bDi + j) * d_state + s1] = run.b1;
267	        }
268	        __syncthreads();
269	    }
270	
271	    // Handle odd d_state
272	    if (d_state % 2 != 0) {
273	        const int s = d_state - 1;
274	        float hv = 0.0f;
275	        for (int step = 0; step < cnt; step++) {
276	            int t = t0 + step;
277	            float dtv = to_float(dt[(bN + t) * d_inner + j]);
278	            float xv  = to_float(x[(bN + t) * d_inner + j]);
279	            hv = ptx_expf(A_coeff[s] * dtv) * hv
280	               + dtv * to_float(B[(bN + t) * d_state + s]) * xv;
281	            float prev = to_float(y[(bN + t) * d_inner + j]);
282	            float cv   = to_float(C[(bN + t) * d_state + s]);
283	            y[(bN + t) * d_inner + j] = from_float<ActT>(prev + hv * cv);
284	        }
285	        if (state_save != nullptr && t1 == N && cnt > 0)
286	            state_save[(bDi + j) * d_state + s] = hv;
287	    }
288	}
289	
290	// ── Forward dispatch ──────────────────────────────────────────────────
291	
292	template <typename ActT>
293	cudaError_t selective_scan_forward(
294	    const ActT* x, const ActT* dt, const ActT* A_log,
295	    const ActT* B, const ActT* C,
296	    ActT* y, float* state_save,
297	    int batch, int seq_len, int d_inner, int d_state,
298	    cudaStream_t stream
299	) {
300	    if (seq_len < PSCAN_THRESHOLD) {
301	        int block = min(d_inner, 128);
302	        dim3 grid((d_inner + block - 1) / block, batch);
303	        sequential_scan_kernel<ActT><<<grid, block, 0, stream>>>(
304	            x, dt, A_log, B, C, y, state_save, seq_len, d_inner, d_state);
305	    } else {
306	        int block = min(PSCAN_BLOCK, 256);
307	        dim3 grid(d_inner, batch);
308	        int smem_bytes = 6 * block * sizeof(float);
309	        parallel_scan_kernel<ActT><<<grid, block, smem_bytes, stream>>>(
310	            x, dt, A_log, B, C, y, state_save, seq_len, d_inner, d_state);
311	    }
312	    return cudaGetLastError();
313	}
314	
315	// ── Backward: adjoint scan ────────────────────────────────────────────
316	// Reverse-time sequential scan computing gradients through the recurrence.
317	// For each timestep t (in reverse):
318	//   grad_h += C[t] * grad_y[t]
319	//   grad_B[t] = dt[t] * x[t] * grad_h
320	//   grad_C[t] = h[t] * grad_y[t]   (h[t] recomputed via forward pass)
321	//   grad_x[t] = sum_s(B[t,s] * dt[t] * grad_h[s])
322	//   grad_dt[t] = sum_s(A[s]*A_bar*h[t-1,s] + B[t,s]*x[t]) * grad_h[s]
323	//   grad_A_log[j,s] += dt[t]*A[s]*A_bar * h[t-1,s] * grad_h[s]
324	//   grad_h = A_bar * grad_h   (backprop through recurrence)
325	
326	// Gradient checkpointing replaces the O(seq_len * d_state) per-thread h_all
327	// buffer (128 KB at seq_len=256, d_state=128) with O(sqrt(seq_len) * d_state)
328	// checkpoint + segment buffers (~17 KB), enabling nvcc to compile the kernel.
329	static constexpr int BW_CKPT_STRIDE = 32;
330	static constexpr int BW_MAX_SEQ     = 1024;
331	static constexpr int BW_MAX_SEGS    = BW_MAX_SEQ / BW_CKPT_STRIDE;
332	
333	template <typename ActT>
334	__global__ void __launch_bounds__(128, 2)
335	scan_backward_kernel(
336	    const ActT* __restrict__ grad_y,
337	    const ActT* __restrict__ x,
338	    const ActT* __restrict__ dt,
339	    const ActT* __restrict__ A_log,
340	    const ActT* __restrict__ B,
341	    const ActT* __restrict__ C,
342	    const float* __restrict__ state_save,
343	    ActT* __restrict__ grad_x,
344	    ActT* __restrict__ grad_dt,
345	    float* __restrict__ grad_A_log,  // [d_inner, d_state], atomicAdd
346	    ActT* __restrict__ grad_B,
347	    ActT* __restrict__ grad_C,
348	    int seq_len, int d_inner, int d_state
349	) {
350	    const int b = blockIdx.y;
351	    const int j = blockIdx.x * blockDim.x + threadIdx.x;
352	    if (j >= d_inner) return;
353	
354	    const int bN  = b * seq_len;
355	    const int n_seg = (seq_len + BW_CKPT_STRIDE - 1) / BW_CKPT_STRIDE;
356	
357	    float A[MAX_D_STATE];
358	    #pragma unroll 4
359	    for (int s = 0; s < d_state; s++)
360	        A[s] = -ptx_expf(to_float(A_log[j * d_state + s]));
361	
362	    // Checkpoint buffer: h state at segment boundaries.
363	    // h_ckpt[seg] = hidden state BEFORE timestep (seg * BW_CKPT_STRIDE).
364	    float h_ckpt[BW_MAX_SEGS * MAX_D_STATE];
365	
366	    // Segment recompute buffer: h[seg_start-1 .. seg_end].
367	    // h_seg[0] = checkpoint (h before first timestep), h_seg[i+1] = h after step i.
368	    float h_seg[(BW_CKPT_STRIDE + 1) * MAX_D_STATE];
369	
370	    // Forward pass: store checkpoint at each segment boundary
371	    float h_run[MAX_D_STATE];
372	    #pragma unroll 4
373	    for (int s = 0; s < d_state; s++) {
374	        h_run[s] = 0.0f;
375	        h_ckpt[s] = 0.0f;
376	    }
377	
378	    for (int t = 0; t < seq_len; t++) {
379	        float xv  = to_float(x[(bN + t) * d_inner + j]);
380	        float dtv = to_float(dt[(bN + t) * d_inner + j]);
381	        #pragma unroll 4
382	        for (int s = 0; s < d_state; s++) {
383	            float A_bar = ptx_expf(A[s] * dtv);
384	            float B_bar = dtv * to_float(B[(bN + t) * d_state + s]);
385	            h_run[s] = A_bar * h_run[s] + B_bar * xv;
386	        }
387	        if ((t + 1) % BW_CKPT_STRIDE == 0) {
388	            int ci = (t + 1) / BW_CKPT_STRIDE;
389	            #pragma unroll 4
390	            for (int s = 0; s < d_state; s++)
391	                h_ckpt[ci * d_state + s] = h_run[s];
392	        }
393	    }
394	
395	    // Reverse pass: process segments from last to first
396	    float grad_h[MAX_D_STATE];
397	    float grad_A_acc[MAX_D_STATE];
398	    #pragma unroll 4
399	    for (int s = 0; s < d_state; s++) { grad_h[s] = 0.0f; grad_A_acc[s] = 0.0f; }
400	
401	    for (int seg = n_seg - 1; seg >= 0; seg--) {
402	        const int seg_start = seg * BW_CKPT_STRIDE;
403	        const int seg_end   = min(seg_start + BW_CKPT_STRIDE, seq_len);
404	        const int seg_len   = seg_end - seg_start;
405	
406	        // Load checkpoint: h_seg[0] = h state before seg_start
407	        #pragma unroll 4
408	        for (int s = 0; s < d_state; s++)
409	            h_seg[s] = h_ckpt[seg * d_state + s];
410	
411	        // Recompute forward through segment to fill h_seg[1..seg_len]
412	        for (int i = 0; i < seg_len; i++) {
413	            int t = seg_start + i;
414	            float xv  = to_float(x[(bN + t) * d_inner + j]);
415	            float dtv = to_float(dt[(bN + t) * d_inner + j]);
416	            #pragma unroll 4
417	            for (int s = 0; s < d_state; s++) {
418	                float A_bar = ptx_expf(A[s] * dtv);
419	                float B_bar = dtv * to_float(B[(bN + t) * d_state + s]);
420	                h_seg[(i + 1) * d_state + s] = A_bar * h_seg[i * d_state + s] + B_bar * xv;
421	            }
422	        }
423	
424	        // Backward through segment (reverse)
425	        for (int i = seg_len - 1; i >= 0; i--) {
426	            int t = seg_start + i;
427	            float xv   = to_float(x[(bN + t) * d_inner + j]);
428	            float dtv  = to_float(dt[(bN + t) * d_inner + j]);
429	            float gy   = to_float(grad_y[(bN + t) * d_inner + j]);
430	
431	            float grad_x_acc  = 0.0f;
432	            float grad_dt_acc = 0.0f;
433	
434	            #pragma unroll 4
435	            for (int s = 0; s < d_state; s++) {
436	                float A_bar = ptx_expf(A[s] * dtv);
437	                float bv    = to_float(B[(bN + t) * d_state + s]);
438	                float cv    = to_float(C[(bN + t) * d_state + s]);
439	                float h_t   = h_seg[(i + 1) * d_state + s];
440	                float h_tm1 = h_seg[i * d_state + s];
441	
442	                grad_C[(bN + t) * d_state + s] = from_float<ActT>(h_t * gy);
443	                grad_h[s] += cv * gy;
444	                grad_B[(bN + t) * d_state + s] = from_float<ActT>(dtv * xv * grad_h[s]);
445	                grad_x_acc += bv * dtv * grad_h[s];
446	                grad_dt_acc += (A[s] * A_bar * h_tm1 + bv * xv) * grad_h[s];
447	                grad_A_acc[s] += dtv * A[s] * A_bar * h_tm1 * grad_h[s];
448	                grad_h[s] = A_bar * grad_h[s];
449	            }
450	
451	            grad_x[(bN + t) * d_inner + j]  = from_float<ActT>(grad_x_acc);
452	            grad_dt[(bN + t) * d_inner + j] = from_float<ActT>(grad_dt_acc);
453	        }
454	    }
455	
456	    #pragma unroll 4
457	    for (int s = 0; s < d_state; s++)
458	        atomicAdd(&grad_A_log[j * d_state + s], grad_A_acc[s]);
459	}
460	
461	// ── Backward dispatch ─────────────────────────────────────────────────
462	
463	template <typename ActT>
464	cudaError_t selective_scan_backward(
465	    const ActT* grad_y,
466	    const ActT* x, const ActT* dt, const ActT* A_log,
467	    const ActT* B, const ActT* C,
468	    const float* state_save,
469	    ActT* grad_x, ActT* grad_dt, float* grad_A_log,
470	    ActT* grad_B, ActT* grad_C,
471	    int batch, int seq_len, int d_inner, int d_state,
472	    cudaStream_t stream
473	) {
474	    cudaMemsetAsync(grad_A_log, 0, d_inner * d_state * sizeof(float), stream);
475	    int block = min(d_inner, 128);
476	    dim3 grid((d_inner + block - 1) / block, batch);
477	    scan_backward_kernel<ActT><<<grid, block, 0, stream>>>(
478	        grad_y, x, dt, A_log, B, C, state_save,
479	        grad_x, grad_dt, grad_A_log, grad_B, grad_C,
480	        seq_len, d_inner, d_state);
481	    return cudaGetLastError();
482	}
483	
484	}}}}  // namespace sg::sm90::models::mamba_adapter
